$provider=$null;$desktop=$null;$service=$null;$checks=0
function Check($Value,$Name){if(!$Value){throw "CHECK FAILED: $Name"};$script:checks++;Write-Output "PASS $Name"}
function Wait-For([scriptblock]$Probe,$Name,[int]$Seconds=30){$end=[DateTime]::UtcNow.AddSeconds($Seconds);while([DateTime]::UtcNow-lt$end){if(& $Probe){return};Start-Sleep -Milliseconds 40};throw "TIMEOUT $Name"}
function Api($Path,$Data=$null){$p=@{Uri=$script:origin+$Path;Headers=@{Authorization='Bearer memory-activities-session'};TimeoutSec=10};if($null-ne$Data){$p.Method='Post';$p.ContentType='application/json';$p.Body=[Text.Encoding]::UTF8.GetBytes(($Data|ConvertTo-Json -Depth 50 -Compress))};Invoke-RestMethod @p}
function Plan($Items,[int]$Delay=0){@{nonce=[Guid]::NewGuid().ToString('N');responses=@($Items|ForEach-Object {@{response=$_;delay_ms=$Delay}})}|ConvertTo-Json -Depth 50|Set-Content (Join-Path $root provider/plan.json) -Encoding utf8}
function Review($Items){@{nonce=[Guid]::NewGuid().ToString('N');responses=@($Items|ForEach-Object {@{response=$_}})}|ConvertTo-Json -Depth 50|Set-Content (Join-Path $root provider/review-plan.json) -Encoding utf8}
function Tool($Id,$Name,$Arguments){@{id=$Id;tool=$Name;args=$Arguments}}
function Calls($Items){@{version=1;kind='call';text=$null;calls=@($Items)}}
function Reply($Text){@{version=1;kind='reply';text=$Text;calls=@();presentation=@{speech=$false;bubble=$false}}}
function Silence{@{version=1;kind='silence';text=$null;calls=@()}}
function Message($Text){$accepted=Api '/api/message' @{request_id=[Guid]::NewGuid().ToString('N');text=$Text};Wait-For {!(Api '/api/chat').busy} 'turn';return $accepted}
function Feedback{$capture=Get-Content (Join-Path $root provider/last-request.json) -Raw|ConvertFrom-Json -Depth 60;@(($capture.messages[-1].content|ConvertFrom-Json -Depth 50).tool_results)}
function Widget{(Api '/api/capabilities').plugins.Where({$_.id-eq'widget'})[0].current}
function World{(Api '/api/capabilities').plugins.Where({$_.id-eq'habitat'})[0].current}
function Plugin($Name,$Arguments){$null=Api '/api/plugin/test' @{tool=$Name;args=$Arguments};Wait-For {$script:receipt=Api '/api/plugin/result';$script:receipt.state-in@('succeeded','failed')} $Name;return $script:receipt.result}
